<?php
namespace App\Http\Controllers; use App\Models\{Product,Category,Brand};
class StoreController extends Controller {public function home(){return view('store.home',['products'=>Product::with('skus')->where('is_active',1)->latest('product_id')->take(12)->get(),'categories'=>Category::orderBy('name')->take(12)->get()]);}public function products(\Illuminate\Http\Request $r){$q=$r->string('q')->toString();$cat=$r->integer('category');$brand=$r->integer('brand');$products=Product::with(['skus','category','brand'])->where('is_active',1)->when($q,fn($x)=>$x->where('name','like',"%$q%"))->when($cat,fn($x)=>$x->where('category_id',$cat))->when($brand,fn($x)=>$x->where('brand_id',$brand))->latest('product_id')->paginate(12)->withQueryString();return view('store.products',['products'=>$products,'categories'=>Category::orderBy('name')->get(),'brands'=>Brand::orderBy('name')->get(),'q'=>$q,'cat'=>$cat,'brand'=>$brand]);}public function show(Product $product){abort_unless($product->is_active,404);$product->load(['category','brand','skus.attributeValues.attribute','reviews.user']);return view('store.show',compact('product'));}}
